parameters.jsCode:
// The model's answer arrives as TEXT inside a response wrapper.
// Pull it out, find the JSON, and turn it into usable data.

const response = $input.first().json;

if (!response.choices || response.choices.length === 0) {
  throw new Error(
    'AI returned no choices. Check the API key and model name. Raw: ' +
    JSON.stringify(response).slice(0, 400)
  );
}

const raw = response.choices[0].message.content ?? '';
const finishReason = response.choices[0].finish_reason;

// Grab everything between the first { and the last } — this survives the
// model adding a stray sentence or wrapping the answer in code fences.
const match = raw.match(/\{[\s\S]*\}/);

if (!match) {
  if (finishReason === 'length') {
    throw new Error(
      'AI response was cut off before the JSON closed. ' +
      'Increase max_tokens in the Mood AI node (thinking models need headroom).'
    );
  }
  throw new Error('No JSON found in AI response: ' + raw);
}

let aiData;
try {
  aiData = JSON.parse(match[0]);
} catch (e) {
  throw new Error('AI returned malformed JSON: ' + match[0].slice(0, 300));
}

for (const field of ['mood_label', 'playlist_name', 'search_query', 'reply']) {
  if (!aiData[field]) {
    throw new Error('AI response is missing the field: ' + field);
  }
}

// Reach back to node 1 for the return address.
const chatId = $('User message').first().json.message.chat.id;

return [{
  json: {
    mood_label: aiData.mood_label,
    playlist_name: aiData.playlist_name,
    search_query: aiData.search_query,
    reply: aiData.reply,
    chat_id: chatId
  }
}];

// Spotify's search response is huge — album art in three sizes, artist
// objects, release dates. We need one thing per track: its URI.
// Playlists cannot be built from song names; URIs are exact.

const tracks = $input.first().json.tracks?.items ?? [];

if (tracks.length === 0) {
  throw new Error(
    'Spotify returned no tracks for: ' + $('Parse AI').first().json.search_query
  );
}

const uris = tracks
  .filter(t => t && typeof t.uri === 'string')
  .slice(0, 10)
  .map(t => t.uri);

if (uris.length === 0) {
  throw new Error('Spotify returned results but none had a usable track URI');
}

// Carry the rest forward — the Spotify response doesn't contain any of it.
return [{
  json: {
    track_uris: uris,
    playlist_name: $('Parse AI').first().json.playlist_name,
    reply: $('Parse AI').first().json.reply,
    chat_id: $('Parse AI').first().json.chat_id
  }
}];

